<?php
// PhpAgent v2 - exhaustive built-in function index + language constructs.
// The function list is generated by tools/generate-function-index.php from
// reflection on a real PHP install. No function descriptions are invented:
// an entry carries name, extension, signature, deprecation flag, php.net
// link, and a link to a verified curated example when one already exists.
// Language constructs are NOT functions and are kept in a separate file.

declare(strict_types=1);

final class FunctionIndex
{
    /** @var array<string, array<string, mixed>> lowercase name => entry */
    private array $functions = [];

    /** @var array<string, mixed> */
    private array $meta = [];

    /** @var array<int, array<string, mixed>> */
    private array $constructs = [];

    public function __construct(string $dataDir)
    {
        $indexFile = rtrim($dataDir, '/') . '/all-functions.json';
        $raw = @file_get_contents($indexFile);
        if ($raw !== false) {
            $decoded = json_decode($raw, true);
            if (is_array($decoded) && isset($decoded['functions']) && is_array($decoded['functions'])) {
                $this->meta = $decoded;
                foreach ($decoded['functions'] as $fn) {
                    if (isset($fn['name'])) {
                        $this->functions[strtolower((string) $fn['name'])] = $fn;
                    }
                }
            }
        }
        $constructsFile = rtrim($dataDir, '/') . '/language-constructs.json';
        $cRaw = @file_get_contents($constructsFile);
        if ($cRaw !== false) {
            $decoded = json_decode($cRaw, true);
            if (is_array($decoded)) {
                $this->constructs = $decoded;
            }
        }
    }

    public static function create(?string $dataDir = null): self
    {
        return new self($dataDir ?? (__DIR__ . '/../data'));
    }

    public function count(): int
    {
        return count($this->functions);
    }

    public function phpVersion(): string
    {
        return (string) ($this->meta['php_version'] ?? PHP_VERSION);
    }

    /** @return array<int, string> */
    public function extensions(): array
    {
        $exts = $this->meta['extensions'] ?? get_loaded_extensions();
        return is_array($exts) ? array_values(array_map('strval', $exts)) : [];
    }

    /** @return array<string, mixed>|null */
    public function find(string $name): ?array
    {
        $key = strtolower(trim($name));
        return $this->functions[$key] ?? null;
    }

    /** @return array<string, mixed>|null */
    public function findConstruct(string $name): ?array
    {
        $key = strtolower(trim($name));
        foreach ($this->constructs as $construct) {
            $title = strtolower((string) ($construct['title'] ?? ''));
            if (str_starts_with($title, $key . ' ') || $title === $key) {
                return $construct;
            }
            foreach ((array) ($construct['keywords'] ?? []) as $keyword) {
                if (strtolower((string) $keyword) === $key) {
                    return $construct;
                }
            }
        }
        return null;
    }

    /** @return array<int, array<string, mixed>> */
    public function constructs(): array
    {
        return $this->constructs;
    }

    /**
     * Closest built-in names to a misspelled name, deterministic order.
     *
     * @return array<int, string>
     */
    public function closest(string $name, int $limit = 5): array
    {
        $key = strtolower(trim($name));
        $scored = [];
        foreach ($this->functions as $fnName => $fn) {
            $distance = levenshtein($key, $fnName);
            $scored[] = ['name' => (string) $fn['name'], 'distance' => $distance];
        }
        usort($scored, function ($a, $b) {
            $byDistance = $a['distance'] <=> $b['distance'];
            if ($byDistance !== 0) {
                return $byDistance;
            }
            return strcmp($a['name'], $b['name']);
        });
        $out = [];
        foreach (array_slice($scored, 0, $limit) as $item) {
            $out[] = $item['name'];
        }
        return $out;
    }

    /** @return array<int, string> */
    public function namesByExtension(string $extension): array
    {
        $out = [];
        foreach ($this->functions as $fn) {
            if (strcasecmp((string) ($fn['extension'] ?? ''), $extension) === 0) {
                $out[] = (string) $fn['name'];
            }
        }
        sort($out, SORT_STRING);
        return $out;
    }

    /** @return array<int, string> */
    public function deprecatedNames(): array
    {
        $out = [];
        foreach ($this->functions as $fn) {
            if (!empty($fn['is_deprecated'])) {
                $out[] = (string) $fn['name'];
            }
        }
        sort($out, SORT_STRING);
        return $out;
    }
}
